import shutil

def clean_and_restructure_data(src_dir, clean_dir):
    """Copy only valid images to a clean directory structure"""
    valid_extensions = {'.jpg', '.jpeg', '.png', '.gif', '.bmp', '.JPG', '.JPEG', '.PNG', '.GIF', '.BMP'}

    if os.path.exists(clean_dir):
        shutil.rmtree(clean_dir)

    if not os.path.exists(src_dir):
        os.makedirs(clean_dir, exist_ok=True)
        return

    for class_name in os.listdir(src_dir):
        class_path = os.path.join(src_dir, class_name)
        if not os.path.isdir(class_path):
            continue

        dest_class_path = os.path.join(clean_dir, class_name)
        os.makedirs(dest_class_path, exist_ok=True)

        for file in os.listdir(class_path):
            file_path = os.path.join(class_path, file)
            if os.path.splitext(file)[1] in valid_extensions:
                dest_file = os.path.join(dest_class_path, file)
                shutil.copy2(file_path, dest_file)

# Clean the training data
clean_and_restructure_data('data_small', 'data_small_clean')
clean_and_restructure_data('data_small_test', 'data_small_test_clean')

